function entryKey(name: string) {
  return name.toLowerCase().replace(/\s+/g, "");
}

/** 同名只留一条。有一边要联网，合并后仍要联网。 */
export function dedupeMarketEntries(entries: McpMarketEntry[]): McpMarketEntry[] {
  const merged = new Map<string, McpMarketEntry>();
  for (const item of entries) {
    const key = entryKey(item.name);
    const prev = merged.get(key);
    if (!prev) {
      merged.set(key, { ...item });
      continue;
    }
    merged.set(key, {
      ...prev,
      needsOnline: prev.needsOnline || item.needsOnline,
      hosted: prev.hosted || item.hosted,
      summary: prev.summary.length >= item.summary.length ? prev.summary : item.summary,
    });
  }
  return [...merged.values()];
}

export function offlineDeploy() {
  return import.meta.env.VITE_ORBIT_OFFLINE === "1";
}

/** 离线部署只留下不需要联网的服务。 */
export function entriesForDeploy(entries: McpMarketEntry[] = MCP_MARKET_ENTRIES) {
  const unique = dedupeMarketEntries(entries);
  if (!offlineDeploy()) return unique;
  return unique.filter((item) => !item.needsOnline);
}
